        return this.extraInterfaces(java.io.Serializable.class);
    }

    public MockSettings extraInterfaces(Class<?>... extraInterfaces) {
        if (extraInterfaces == null || extraInterfaces.length == 0) {
            new Reporter().extraInterfacesRequiresAtLeastOneInterface();
        }

        for (int idx = 0; idx < extraInterfaces.length; idx++) {
            Class<?> current = extraInterfaces[idx];
            if (current == null) {
                new Reporter().extraInterfacesDoesNotAcceptNullParameters();
            } else if (!current.isInterface()) {
                new Reporter().extraInterfacesAcceptsOnlyInterfaces(current);
            }
        }
