        this.instanceBeingSpied = spiedInstance;
        return this;
    }

    @SuppressWarnings("unchecked")
    public MockSettings defaultAnswer(Answer defaultAnswer) {
        this.answerForDefault = defaultAnswer;
        return this;
    }

    public Answer<Object> getDefaultAnswer() {
        return answerForDefault;
    }

    public boolean isSerializable() {
        if (additionalInterfaceTypes == null) {
            return false;
        }
        return java.util.Arrays.asList(additionalInterfaceTypes).contains(java.io.Serializable.class);
